describe('Search Results Debounce Functionality', () => {
  beforeEach(() => {
    cy.visit('/search');
  });

  it('should update search results only after 300ms debounce delay', () => {
    // Intercept the search API call
    cy.intercept('GET', '/api/search*').as('searchRequest');

    // Type first search term
    cy.get('[data-testid="search-input"]').type('apple');

    // Wait for debounce delay
    cy.wait(350);

    // Verify API call was made
    cy.wait('@searchRequest');

    // Verify results are displayed
    cy.get('[data-testid="search-results"]').should('be.visible');
    cy.get('[data-testid="result-item"]').should('contain', 'Apple');

    // Type second search term
    cy.get('[data-testid="search-input"]').clear().type('banana');

    // Wait for debounce delay
    cy.wait(350);

    // Verify second API call was made
    cy.wait('@searchRequest');

    // Verify results are updated
    cy.get('[data-testid="search-results"]').should('be.visible');
    cy.get('[data-testid="result-item"]').should('contain', 'Banana');
  });

  it('should not trigger API call for rapid typing within debounce window', () => {
    // Intercept the search API call
    cy.intercept('GET', '/api/search*').as('searchRequest');

    // Type multiple characters rapidly
    cy.get('[data-testid="search-input"]').type('apple');

    // Wait for debounce delay
    cy.wait(350);

    // Verify only one API call was made
    cy.wait('@searchRequest');

    // Verify results are displayed
    cy.get('[data-testid="search-results"]').should('be.visible');
    cy.get('[data-testid="result-item"]').should('contain', 'Apple');

    // Clear and type again rapidly
    cy.get('[data-testid="search-input"]').clear().type('orange');

    // Wait for debounce delay
    cy.wait(350);

    // Verify second API call was made
    cy.wait('@searchRequest');

    // Verify results are updated
    cy.get('[data-testid="search-results"]').should('be.visible');
    cy.get('[data-testid="result-item"]').should('contain', 'Orange');
  });
});
